import audited from './exercise-muscles.json' with { type: 'json' }

/**
 * Reviewed primary/secondary muscles for every built-in exercise except cardio, generated by
 * scripts/audit-exercise-muscles.mjs (the movement-family rules and their rationale live
 * there). The raw generated catalogue stays untouched; exercises.js applies this as a runtime
 * overlay. Values are lib/muscles.js slugs plus 'lats' and 'rear-delts', which the muscle map
 * folds into upper-back / deltoids and the volume split keeps apart.
 */
export const EXERCISE_MUSCLES = Object.freeze(audited)

// Lifts that train more than the dataset's body part says: the whole posterior chain or a
// squat under an overhead load is Full body, a band straight-leg deadlift is legs.
const BODYPART = Object.freeze({
  '0032': 'full body', '0066': 'full body', '0069': 'full body', '0117': 'full body',
  '0157': 'full body', '0752': 'full body', '0786': 'full body', '0811': 'full body',
  '3418': 'full body', '1010': 'upper legs',
})

export function exerciseMuscleMetadataFor(id) {
  return {
    ...(BODYPART[id] ? { bp: BODYPART[id] } : {}),
    ...(EXERCISE_MUSCLES[id] || {}),
  }
}
